package com.example.e2e.metrics;

import com.example.e2e.logging.Outcomes;

/**
 * Metric names, in one place: call sites call a member here and never name a metric.
 * Generated by logast (metrics.catalog). Rename or document members freely; logast keeps them and adds new
 * ones at the end.
 */
// logast:metrics-catalog
public final class BusinessMetrics {
    private BusinessMetrics() {
    }

    /** Observation (timer and span) name. */
    public static final String PUBLISHING = "publishing";

    /** Observation (timer and span) name. */
    public static final String SETTLEMENT_JOB_EXECUTOR_ON_READY = "settlement-job-executor.on-ready";

    /** Observation (timer and span) name. */
    public static final String COUPON_MESSAGES_ON_BATCH = "coupon-messages.on-batch";

    /** Observation (timer and span) name. */
    public static final String ORDER_NOTIFICATIONS = "order.notifications";

    /** outcome="failed" on the timer already running (same thread). */
    public static void tagFailed() {
        Outcomes.tag("failed");
    }

    /** coupons{outcome="updated"} +1; rows is one sample of the distribution coupons.rows{outcome="updated"}. */
    public static void couponsUpdated(Number rows) {
        Outcomes.record("coupons", "updated", "rows", rows);
    }

    /** coupon.usage{outcome="saved"} +1; coupon.usage.uses{outcome="saved"} grows by uses. */
    public static void couponUsageSaved(Number uses) {
        Outcomes.count("coupon.usage", "saved", "uses", uses);
    }

    /** coupon{outcome="sent"} +1. */
    public static void couponSent() {
        Outcomes.count("coupon", "sent");
    }

    /** coupon.resend{outcome="failed"} +1. */
    public static void couponResendFailed() {
        Outcomes.count("coupon.resend", "failed");
    }

    /** coupon{outcome="published"} +1. */
    public static void couponPublished() {
        Outcomes.count("coupon", "published");
    }

    /** coupon.redemption{outcome="completed"} +1. */
    public static void couponRedemptionCompleted() {
        Outcomes.count("coupon.redemption", "completed");
    }

    /** coupon{outcome="audited"} +1. */
    public static void couponAudited() {
        Outcomes.count("coupon", "audited");
    }

    /** coupon{outcome="parsed"} +1. */
    public static void couponParsed() {
        Outcomes.count("coupon", "parsed");
    }

    /** edge.processing{outcome="completed"} +1. */
    public static void edgeProcessingCompleted() {
        Outcomes.count("edge.processing", "completed");
    }

    /** calculation{outcome="completed"} +1. */
    public static void calculationCompleted() {
        Outcomes.count("calculation", "completed");
    }

    /** export.job{outcome="completed"} +1. */
    public static void exportJobCompleted() {
        Outcomes.count("export.job", "completed");
    }

    /** preload.export{outcome="completed"} +1. */
    public static void preloadExportCompleted() {
        Outcomes.count("preload.export", "completed");
    }

    /** coupon.messages{outcome="completed"} +1. */
    public static void couponMessagesCompleted() {
        Outcomes.count("coupon.messages", "completed");
    }

    /** order.confirmation{outcome="sent"} +1. */
    public static void orderConfirmationSent() {
        Outcomes.count("order.confirmation", "sent");
    }

    /** order{outcome="placed"} +1. */
    public static void orderPlaced() {
        Outcomes.count("order", "placed");
    }

    /** order.shipment{outcome="skipped"} +1. */
    public static void orderShipmentSkipped() {
        Outcomes.count("order.shipment", "skipped");
    }

    /** orders{outcome="shipped"} +1; orders.items{outcome="shipped"} grows by items. */
    public static void ordersShipped(Number items) {
        Outcomes.count("orders", "shipped", "items", items);
    }

    /** Registers this catalog's counters at 0 when the application has started: a series exists before the first event. */
    @org.springframework.stereotype.Component
    static final class Registration implements org.springframework.beans.factory.SmartInitializingSingleton {
        @Override
        public void afterSingletonsInstantiated() {
            Outcomes.registerPerRun("coupons", "updated", "rows");
            Outcomes.registerTotal("coupon.usage", "saved", "uses");
            Outcomes.register("coupon", "sent");
            Outcomes.register("coupon.resend", "failed");
            Outcomes.register("coupon", "published");
            Outcomes.register("coupon.redemption", "completed");
            Outcomes.register("coupon", "audited");
            Outcomes.register("coupon", "parsed");
            Outcomes.register("edge.processing", "completed");
            Outcomes.register("calculation", "completed");
            Outcomes.register("export.job", "completed");
            Outcomes.register("preload.export", "completed");
            Outcomes.register("coupon.messages", "completed");
            Outcomes.register("order.confirmation", "sent");
            Outcomes.register("order", "placed");
            Outcomes.register("order.shipment", "skipped");
            Outcomes.registerTotal("orders", "shipped", "items");
        }
    }
}
